SELECT source_session_revision, closed_epoch_second, closed_nano, retired_through_sequence,
       retired_event_count, retired_reasoning_count, status
  FROM public.agent_runtime_session_history_retirements
 WHERE tenant_id=#{owner.sessionRef.tenantId.value} AND session_id=#{owner.sessionRef.sessionId}
   AND target_kind=#{owner.target.kind} AND target_id=#{owner.target.id} AND end_user_id IS NOT DISTINCT FROM NULL#{owner.requireUser.value}

SELECT event_id, session_sequence, event_digest FROM public.agent_runtime_session_event_tombstones
 WHERE tenant_id=#{owner.sessionRef.tenantId.value} AND session_id=#{owner.sessionRef.sessionId}
   AND target_kind=#{owner.target.kind} AND target_id=#{owner.target.id} AND end_user_id IS NOT DISTINCT FROM NULL#{owner.requireUser.value}
   AND event_id IN #{id}

SELECT tenant_id, session_id, target_kind, target_id, end_user_id
 FROM public.agent_runtime_session_owners
 WHERE tenant_id = #{tenantId}
   AND target_kind = #{targetKind}
   AND target_id = #{targetId}
   AND session_id = #{sessionId}
 FOR UPDATE

SELECT tenant_id, session_id, target_kind, target_id, end_user_id, next_sequence
 FROM public.agent_runtime_session_streams
 WHERE tenant_id = #{tenantId}
   AND target_kind = #{targetKind}
   AND target_id = #{targetId}
   AND session_id = #{sessionId}
 FOR UPDATE

SELECT 
  FROM public.agent_runtime_session_events
 WHERE tenant_id = #{tenantId}
   AND session_id = #{sessionId}
   AND target_kind = #{targetKind}
   AND target_id = #{targetId}
   AND end_user_id IS NOT DISTINCT FROM #{endUserId}
   AND event_id = #{eventId}

SELECT 
  FROM public.agent_runtime_session_events e
 WHERE e.tenant_id=#{tenantId} AND e.session_id=#{sessionId}
   AND e.end_user_id=#{endUserId}
   AND e.target_kind<>'GROUP' AND e.event_id=#{eventId}
   AND EXISTS (SELECT 1 FROM public.agent_runtime_session_owners o
        WHERE o.tenant_id=e.tenant_id AND o.session_id=e.session_id
          AND o.target_kind=e.target_kind AND o.target_id=e.target_id
          AND o.subject_kind='USER' AND o.end_user_id=e.end_user_id)
 ORDER BY e.target_kind,e.target_id LIMIT 2

SELECT content_hash,canonical_content FROM public.agent_runtime_session_event_bodies
 WHERE tenant_id=#{row.tenantId} AND target_kind=#{row.targetKind} AND target_id=#{row.targetId}
   AND session_id=#{row.sessionId} AND end_user_id IS NOT DISTINCT FROM #{row.endUserId} AND content_hash IN
   #{digest}
 FOR KEY SHARE

