SELECT  FROM public.agent_runtime_session_events
WHERE tenant_id=#{tenantId} AND session_id=#{sessionId} AND target_kind=#{targetKind}
  AND target_id=#{targetId} AND end_user_id IS NOT DISTINCT FROM #{endUserId}
ORDER BY session_sequence DESC LIMIT 1

SELECT  FROM public.agent_runtime_session_events
WHERE tenant_id=#{tenantId} AND session_id=#{sessionId} AND target_kind=#{targetKind}
  AND target_id=#{targetId} AND end_user_id IS NOT DISTINCT FROM #{endUserId} AND run_id=#{runId}
  AND session_sequence > #{afterSequence}

  AND event_type IN
  #{type}

ORDER BY session_sequence ASC LIMIT #{limit}

SELECT  FROM public.agent_runtime_session_events
WHERE tenant_id=#{tenantId} AND session_id=#{sessionId} AND target_kind=#{targetKind}
  AND target_id=#{targetId} AND end_user_id IS NOT DISTINCT FROM #{endUserId}
  AND input_id=#{inputId} AND run_id=#{runId}
ORDER BY session_sequence ASC LIMIT 1
